async function selectLayer(name){
  var state=await app.getAXState({emit:false,disableDiffing:true});
  var esc=name.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');
  var re=new RegExp("^\\s*(\\d+) row(?: \\(selected\\))? "+esc+"(?: |$).*$","m");
  var m=state.match(re); if(!m) throw new Error("Layer not found: "+name);
  await app.click(Number(m[1]));
  return Number(m[1]);
}
async function ensureHidden(name){
  await selectLayer(name);
  var st=await app.getAXState({emit:false,disableDiffing:true});
  var hide=st.match(/^\s*(\d+) checkbox Hide, Value: 0/m);
  if(hide){ await app.click(Number(hide[1])); nodeRepl.write(name+": hidden"); return; }
  var show=st.match(/^\s*(\d+) checkbox Show, Value: 1/m);
  if(show){ nodeRepl.write(name+": already hidden"); return; }
  nodeRepl.write(name+": visibility control not found");
}
