async function selectLayerOccurrence(name,n){
  var state=await app.getAXState({emit:false,disableDiffing:true});
  var esc=name.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');
  var re=new RegExp("^\\s*(\\d+) row(?: \\(selected\\))? "+esc+"(?: |$).*$","gm");
  var ms=[...state.matchAll(re)];
  if(ms.length<n) throw new Error("Layer occurrence not found: "+name+" #"+n+" count="+ms.length);
  await app.click(Number(ms[n-1][1])); return Number(ms[n-1][1]);
}
