async function setFieldFresh(label,value){
  var st=await app.getAXState({emit:false,disableDiffing:true});
  var esc=label.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');
  var re=new RegExp("^\\s*(\\d+) (?:text field|stepper) \\(settable[^\\n]*Description: "+esc+"(?:,[^\\n]*)","m");
  var m=st.match(re);
  if(!m) throw new Error("Field not found: "+label);
  await app.setValue(Number(m[1]),value);
  await app.pressKey("Tab");
  var st2=await app.getAXState({emit:false,disableDiffing:true});
  var m2=st2.match(new RegExp("Description: "+esc+", Value: ([^\\n]+)","m"));
  return m2?m2[1]:"?";
}
